     * @param bidPrice 입찰 가격
     * @return 생성된 주문 입찰
     * @throws OrderBidCreationFailedException 주문 입찰 생성 실패 시
     * @throws ProductSizeNotFoundException 상품 사이즈를 찾을 수 없는 경우
     * @throws InvalidBidPriceException 입찰 가격이 유효하지 않은 경우
     */
    @Transactional
    public OrderBid createOrderBid(String email, Long productSizeId, int bidPrice) {
        try {
            // 1. 입력값 검증
            validateCreateOrderBidInput(email, productSizeId, bidPrice);

            // 2. User 조회
            User user = userQueryService.findByEmail(email);

            // 3. ProductSize 조회
            ProductSize productSize = productSizeQueryService.findById(productSizeId)
                    .orElseThrow(() -> new ProductSizeNotFoundException("해당 사이즈를 찾을 수 없습니다(ID: " + productSizeId + ")"));

            // 4. Order 생성
            Order order = orderCommandService.createOrderFromBid(user, productSize, bidPrice);

            // 5. OrderBid 생성 및 저장
            OrderBid orderBid = createAndSaveOrderBid(user, productSize, bidPrice, order);

            return orderBid;
        } catch (Exception e) {
            handleOrderBidCreationException(e, "주문 입찰 생성");
            return null; // 실행되지 않음 (예외가 던져짐)
        }
    }

    /**
     * 주문 입찰 생성 입력값을 검증합니다.
     */
    private void validateCreateOrderBidInput(String email, Long productSizeId, int bidPrice) {
        if (email == null || email.trim().isEmpty()) {
            throw new OrderBidAccessDeniedException("사용자 이메일이 없습니다.");
        }
        if (productSizeId == null) {
            throw new ProductSizeNotFoundException("상품 사이즈 ID가 없습니다.");
        }
        if (bidPrice <= 0) {
            throw new InvalidBidPriceException("입찰 가격은 0보다 커야 합니다. 현재 가격: " + bidPrice);
        }
    }

    /**
     * OrderBid 생성 및 저장을 수행합니다.
     */
    private OrderBid createAndSaveOrderBid(User user, ProductSize productSize, int bidPrice, Order order) {
        OrderBid orderBid = OrderBid.builder()
                .user(user)
                .productSize(productSize)
                .bidPrice(bidPrice)
                .status(BidStatus.PENDING)
                .order(order)
                .build();

        // 양방향 관계 설정
        orderBid.assignOrder(order);

        return orderBidRepository.save(orderBid);
    }

    /**
     * 즉시 구매 주문 입찰을 생성합니다.
     *
     * @param buyerEmail 구매자 이메일
     * @param saleBidId 판매 입찰 ID
     * @param addressId 배송지 ID
     * @param isWarehouseStorage 창고 보관 여부
     * @param paymentRequest 결제 요청 정보
     * @return 생성된 주문 입찰
     * @throws OrderBidCreationFailedException 주문 입찰 생성 실패 시
     * @throws SaleBidNotFoundException 판매 입찰을 찾을 수 없는 경우

    /**
     * 즉시 구매 OrderBid를 생성합니다.
     */
    private OrderBid createInstantOrderBid(Order order, SaleBid saleBid, Sale sale) {
        ProductSize productSize = saleBid.getProductSize();

        OrderBid orderBid = OrderBid.builder()
                .user(order.getUser()) // 구매자
                .productSize(productSize)
                .bidPrice(saleBid.getBidPrice())
                .status(BidStatus.MATCHED) // 즉시 구매는 바로 매칭 상태
                .order(order) // Order와 매핑
                .sale(sale) // 셀러 정보 추가
                .build();

        // 양방향 관계 설정
        orderBid.assignOrder(order);

        // 플래그 설정 및 저장
        orderBid.markAsInstantPurchase();
        return orderBidRepository.save(orderBid);
    }

    /**
     * 주문 입찰 생성 예외를 처리합니다.
     */
    private void handleOrderBidCreationException(Exception e, String operation) {
        if (e instanceof OrderException) {
            throw (OrderException) e;
        }
        // 1. User 조회
        User seller = userQueryService.findByEmail(sellerEmail);

        // 2. ProductSize 조회
        ProductSize productSize = productSizeQueryService.findById(productSizeId)
                .orElseThrow(() -> new IllegalArgumentException("해당 상품 사이즈를 찾을 수 없습니다: " + productSizeId));

        // 3. Sale 생성
        Sale sale = saleCommandService.createSale(seller, productSize, returnAddress, postalCode, receiverPhone,isWarehouseStorage);

        // 4. SaleBid 생성
        SaleBid saleBid = SaleBid.builder()
                .seller(seller)
                .productSize(productSize)
                .bidPrice(bidPrice)
                .status(BidStatus.PENDING)
                .sale(sale) // 연관된 Sale 설정
                .build();

        // 5. SaleBid 저장
        saleBid = saleBidRepository.save(saleBid);

        // 6. Sale에 SaleBid 추가 (연관관계 설정)
        sale.assignSaleBid(saleBid);

        // 7. SaleBid 반환
        return saleBid;
    }
    @Transactional
    public Long createInstantSaleBid(Long orderBidId,
                                        String sellerEmail,
                                        String returnAddress,
                                        String postalCode,
                                        String receiverPhone) {

        Sale sale=saleCommandService.createInstantSale(orderBidId,sellerEmail,returnAddress,postalCode,receiverPhone);
        // 1. OrderBid 조회
        OrderBid orderBid = orderBidQueryService.findById(orderBidId)
                .orElseThrow(() -> new IllegalArgumentException("해당 OrderBid를 찾을 수 없습니다."));


        // 3. SaleBid 생성
        SaleBid saleBid = SaleBid.builder()
                .seller(sale.getSeller()) // Sale의 판매자
                .productSize(sale.getProductSize()) // Sale의 ProductSize
                .bidPrice(orderBid.getBidPrice()) // OrderBid의 입찰 가격 사용
                .status(BidStatus.MATCHED) // 즉시 판매는 바로 매칭 상태
                .sale(sale) // Sale과 매핑
                .order(orderBid.getOrder()) // Order와 매핑
                .build();

        // 양방향 관계 설정
        saleBid.assignSale(sale);
        saleBid.assignOrder(orderBid.getOrder());
        sale.assignSaleBid(saleBid); // Sale과 SaleBid 양방향 연관관계 설정

        // SaleBid 저장
        saleBidRepository.save(saleBid);

        // Sale ID 반환
        return sale.getId();
    }

    @Transactional
    public void deleteSaleBid(Long saleBidId) {
        // SaleBid 조회
        SaleBid saleBid = saleBidRepository.findById(saleBidId)
                .orElseThrow(() -> new IllegalArgumentException("해당 SaleBid를 찾을 수 없습니다: " + saleBidId));

        // Order와 연결 여부 확인
        if (saleBid.getOrder() != null) {
            throw new IllegalStateException("SaleBid는 Order와 연결되어 있으므로 삭제할 수 없습니다.");
        }

        // Sale과 연결 여부 확인 후 삭제
        if (saleBid.getSale() != null) {
            saleCommandService.deleteSale(saleBid.getSale().getId());
        }

        // SaleBid 삭제
        saleBidRepository.delete(saleBid);
    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "seller_id")
    private User seller; // 판매자 정보

    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "product_size_id")
    private ProductSize productSize; // 판매 대상 상품 사이즈

    private int bidPrice; // 판매자가 원하는 가격

    @Enumerated(EnumType.STRING)
    @Builder.Default
    private BidStatus status = BidStatus.PENDING; // 입찰 상태 (대기 중, 매칭 완료 등)

    @OneToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "sale_id")
    private Sale sale; // 매칭된 판매 엔티티

    @OneToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "order_id")
    private Order order; // 매칭된 구매 엔티티


    // 즉시 판매 플래그
    @Column(nullable = false)
    @Builder.Default
    private boolean isInstantSale = false;

    public void assignSale(Sale sale) {
        this.sale = sale;
        this.status = BidStatus.MATCHED;
    }

    public void assignOrder(Order order) {
        this.order = order;
        this.status = BidStatus.MATCHED;
    }
    public void markAsInstantSale() {
        this.isInstantSale = true;
    }

    public void updateStatus(BidStatus newStatus) {
        this.status = newStatus;
    }
}
     * @param newStatus 새 주문 상태
     * @throws InvalidOrderStatusException 유효하지 않은 상태 전이인 경우
     */
    public void updateStatus(OrderStatus newStatus) {
        if (this.status == null || this.status.canTransitionTo(newStatus)) {
            this.status = newStatus;
        } else {
            throw new InvalidOrderStatusException(
                    String.format("상태 전환이 허용되지 않습니다: %s -> %s", this.status, newStatus)
            );
        }
    }

    /**
     * OrderBid와의 양방향 관계를 설정합니다.
     *
     * @param orderBid 주문 입찰
     */
    public void assignOrderBid(OrderBid orderBid) {
        this.orderBid = orderBid;
        if (orderBid != null && orderBid.getOrder() != this) {
            orderBid.assignOrder(this);
        }
    }
}package com.fream.back.visible.c04;

import com.fream.back.domain.order.entity.BidStatus;
import com.fream.back.domain.order.entity.Order;
import com.fream.back.domain.order.entity.OrderBid;
import com.fream.back.domain.order.repository.OrderBidRepository;
import com.fream.back.domain.order.service.command.OrderBidCommandService;
import com.fream.back.domain.order.service.command.OrderCommandService;
import com.fream.back.domain.product.entity.ProductSize;
import com.fream.back.domain.product.service.productSize.ProductSizeQueryService;
import com.fream.back.domain.sale.service.query.SaleBidQueryService;
import com.fream.back.domain.user.entity.User;
import com.fream.back.domain.user.service.query.UserQueryService;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;

import java.util.Optional;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatCode;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

/**
 * 일반 구매 입찰 등록 직후의 상태와 취소 가능 여부.
 */
@ExtendWith(MockitoExtension.class)
class PurchaseBidRegistrationTest {

    @Mock OrderBidRepository orderBidRepository;
    @Mock OrderCommandService orderCommandService;
    @Mock ProductSizeQueryService productSizeQueryService;
    @Mock UserQueryService userQueryService;
    @Mock SaleBidQueryService saleBidQueryService;

    @InjectMocks OrderBidCommandService service;

    private final User buyer = User.builder().id(1L).email("buyer@test.com").build();
    private final ProductSize size = ProductSize.builder().id(10L).size("260").build();

    private OrderBid register() {
        Order order = Order.builder().id(100L).user(buyer).build();
        when(userQueryService.findByEmail("buyer@test.com")).thenReturn(buyer);
        when(productSizeQueryService.findById(10L)).thenReturn(Optional.of(size));
        when(orderCommandService.createOrderFromBid(buyer, size, 180000)).thenReturn(order);
        when(orderBidRepository.save(any(OrderBid.class))).thenAnswer(inv -> inv.getArgument(0));
        return service.createOrderBid("buyer@test.com", 10L, 180000);
    }

    @Test
    void newPurchaseBidIsWaitingForASeller() {
        OrderBid bid = register();

        assertThat(bid.getStatus()).isEqualTo(BidStatus.PENDING);
        assertThat(bid.getSale()).isNull();
        assertThat(bid.isInstantPurchase()).isFalse();
    }

    @Test
    void newPurchaseBidCanBeCancelled() {
        OrderBid bid = register();
        when(orderBidRepository.findById(55L)).thenReturn(Optional.of(bid));

        assertThatCode(() -> service.deleteOrderBid(55L)).doesNotThrowAnyException();
        verify(orderBidRepository).delete(bid);
    }
}

